function faceZ(x,y){
  const n=Math.sqrt(Math.max(0,1-Math.pow(x/HW,2)-Math.pow((y-HY)/HH,2)));
  const muzzle=.185*Math.exp(-Math.pow((y-2.39)/.34,2))*
    (1-.40*Math.pow(x/HW,2));
  const cheeks=.055*Math.exp(
    -Math.pow((Math.abs(x)-.79)/.24,2)-Math.pow((y-2.37)/.29,2)
  );
  const brows=.045*Math.exp(
    -Math.pow((Math.abs(x)-.48)/.28,2)-Math.pow((y-2.88)/.20,2)
  );
  return n*(HD+muzzle+cheeks+brows);
}

function rimPoint(a){
  const s=Math.sin(a);
  const x=.83*Math.cos(a);
  const y=s>=0
    ?2.43-.12*Math.pow(s,.85)
    :2.43-.64*Math.pow(-s,.82);
  return new THREE.Vector3(x,y-HY,faceZ(x,y));
}

